"""Individually authored editor and hosted-workbench profile expansions."""
from profile_expansions import add

add("B16",
    principle="ZCode 将长任务与目标管理结合，希望代理不仅处理当前一句话，还能保留继续工作的依据。对跨多次会话的改造，这比单纯增加窗口长度更有意义。但目标保存只解决“回来时知道要做什么”，完成判断仍需要测试、文件和需求证据，不能由一句自我报告决定。",
    flow=["ZCode 工作入口\n目标及项目", "工作空间与项目指令\n文件、分支、AGENTS.md", "原生 GLM 路线\n模型及推理档位", "目标状态与任务成果\n恢复和完成检查", "代码与命令环境\n修改及验证", "Agent／Goal Mode\n持续推进任务"],
    mechanism="持续目标可以在一轮结束后帮助决定是否继续，也能在暂停后装载当前进度。真正关键的是恢复材料包含哪些事实：已经改过的文件、验证结果、仍未解决的问题和下一步。若只是重复初始需求，模型仍可能重做工作。项目指令迁移同样需要明确：将旧 CLAUDE.md 导入一次，与每次运行持续读取该文件，是不同机制。",
    rows=[("原生适配", "围绕 GLM-5.3 的官方路线", "产品适配主张与跨产品胜负分开理解"), ("目标管理", "Goal Mode、状态及恢复", "完成标准需外部可查，不能只凭目标状态"), ("项目上下文", "工作空间、文件引用与指令", "让关键约束进入实际读取的文件"), ("迁移规则", "旧指令可作迁移来源，后续使用 AGENTS.md", "修改规则后核对当前任务读取的文件与生效状态"), ("执行设置", "模式、分支与推理档位", "目录隔离、权限和模型能力分别核对"), ("兼容性", "其他 Provider 按实际版本确认", "不把原生模型表现推及任意自定义后端")],
    steps=["导入一个已有仓库，确认模型、项目目录和执行模式；核对当前项目指令实际来自哪里。", "用一个当天可以完成的需求试 Goal Mode，写清完成条件和改动范围，不使用“尽可能完善”这类无终点目标。", "要求在阶段结束保存文件、检查和待办，主动暂停一次，再恢复并核对这些事实。", "实施过程中遇到目标变化，同步更新目标、验收条件和任务清单。", "交付后查看 diff 和真实测试，记录恢复是否减少重复工作；稳定后再扩大任务长度或尝试其他模型路线。"],
    command="text\n长任务检查点建议：\n目标与不可改变的约束\n已完成文件与验证证据\n失败尝试及原因\n下一步和仍需决定的问题\n恢复时先核对检查点，再继续修改。",
    task="分阶段替换项目中的旧配置读取方式。每完成一个模块保存进度与检查结果；暂停后从未完成部分继续，保持旧配置兼容。",
    acceptance="恢复测试要检查是否重复修改已完成模块、是否遗漏兼容要求，以及结束时是否仍有旧调用残留。可以用推进是否准确、完成条件是否满足、停止是否及时来衡量长任务质量。",
    tradeoff="适合 GLM 用户、中文工程沟通和持续目标改造。若需求经常变化，应先建立规范或任务边界；若只修一个小问题，目标模式可能没有额外收益。与 Step Code 比较时看持续控制，与 Kiro 比较时看前期规范，三者不必互相替代。",kind="public")

add("B17",
    principle="Avante 将代理修改带进 Neovim，而不要求熟练用户离开已有键盘工作流。它不仅显示答案，也围绕选中文件、修改建议和差异审查组织使用。对已经维护 Lua 配置的人，这种可定制性很自然；对新手而言，插件依赖、模型接入与编辑器配置会叠加学习成本。",
    flow=["Neovim 缓冲区与侧栏\n选区和项目任务", "Avante Lua 层\n上下文与交互组织", "HTTP Provider／ACP\n模型或外部代理", "回复、摘要与修改建议\n在编辑器审阅", "文件编辑及可用工具\n外部后端有自身能力", "直接工具循环或代理后端\n可选只读调查任务"],
    mechanism="直接 Provider 路线由插件组织模型消息和工具，ACP 路线则把完整代理职责交给外部进程。两者在编辑器里可能看起来相似，但认证、权限和恢复路径不同。源码中的 dispatch_agent 是受限的搜索分派，适合调查而非任意实施；不能看到一个 agent 名称就推断有完整可写团队。修改建议最后仍需按真实 diff 审查。",
    rows=[("工作位置", "Neovim 内的项目对话与编辑", "使用已有缓冲区和键盘习惯"), ("两条后端", "直接模型与 ACP 外部代理", "明确当前由谁管理工具循环"), ("项目规则", "avante.md 等支持的指令", "规则路径与生效范围按版本核对"), ("独立调查", "所核验 dispatch_agent 为只读搜索", "不可据此推定可写团队或无限派生"), ("依赖", "Neovim、插件及部分构建依赖", "先确认基础插件正常，再调模型"), ("成本与权限", "由所选 Provider／外部代理决定", "编辑器统一不代表账户与授权统一")],
    steps=["按当前 README 检查 Neovim 版本与依赖，通过自己的插件管理方式安装；确认界面和必要构建步骤正常。", "先选择一个直接 Provider 或一个 ACP 后端，完成认证；不同时加入检索、多个模型与额外工具。", "选中小段代码，用 AvanteAsk 提出解释或修改，练习查看与接受 diff，确认实际应用位置。", "再让它处理跨文件任务，将长期约定放入文档支持的项目规则；只读调查任务要求返回文件与证据。", "需要外部 ACP 时单独检查代理安装、模型和权限。更新插件或后端后重复一次小修改，防止接口变化影响日常工作。"],
    command="vim\n\" 在 Neovim 中、插件已正确安装后执行\n:AvanteAsk 解释当前函数的输入边界并提出最小修复",
    task="当前函数对空字符串和缺失字段处理不一致。先解释调用方预期，再给出最小修改和测试；不要调整无关格式与接口。",
    acceptance="观察上下文是否来自正确缓冲区、修改能否准确应用到目标范围，以及接受建议后的文件是否符合预期。Neovim 用户还应评估操作是否打断已有编辑节奏，不能只比较回答内容。",
    tradeoff="适合熟练 Neovim 用户和愿意配置工具的人。主要收益是保留工作习惯，代价是插件、依赖和后端的组合维护。与 CodeCompanion 比较交互和工作流设计；需要开箱即用 IDE 体验的人可能更适合商业编辑器或普通扩展。")

add("B18",
    principle="CodeCompanion 把 Neovim 当作可组合的 AI 工作台，提供聊天、局部转换、审查与自定义工作流。它清楚区分模型适配和代理连接，使用户可以按任务选择：简单转换直接请求模型，复杂开发交给完整代理。灵活性很高，但用户要愿意明确每条路线的责任和配置。",
    flow=["Neovim 交互与工作流\n选区、提示和任务", "CodeCompanion 配置层\n上下文、规则与适配器", "HTTP 模型／ACP 代理\n各自认证和能力", "流式更新与结果\n审查、应用和继续", "工具或外部执行环境\n代码及命令", "HTTP 组织逻辑／ACP 会话\n分开处理运行责任"],
    mechanism="HTTP Adapter 处理的是向模型发请求、解析流和工具格式；ACP Connection 处理的是与一个会自己执行任务的代理交流，包括会话更新与权限请求。前者类似给模型接插座，后者类似接一位完整同事。排错时先辨认这层边界：模型参数不支持与外部代理无法启动，不应采用同一种修复办法。",
    rows=[("交互", "Chat、局部转换、审查和工作流", "根据编辑尺度选择，不把所有操作变成长任务"), ("HTTP Adapter", "模型消息与工具格式适配", "兼容服务需核对参数和返回格式"), ("ACP Connection", "外部代理会话、能力及审批", "代理模型与权限在相应后端配置"), ("规则和扩展", "可按需接规则、Skills、MCP 等", "配置越多，越需保留最小可用基线"), ("运行责任", "插件与外部代理分工明确", "同一界面下可能有不同状态保存方式"), ("维护", "编辑器、插件和后端共同变化", "升级分批进行，便于定位失效层")],
    steps=["安装符合当前要求的插件，先选 HTTP 或 ACP 一条路线；完成对应认证，确认简单提问能返回结果。", "从局部转换开始，如解释函数或改写注释，检查选区与输出插入方式；熟悉后再处理文件级修改。", "将重复提示整理成工作流，明确输入、输出和可用工具。先用最小配置完成任务，再逐项加入需要的社区扩展。", "复杂任务接外部代理时，先在其自身入口验证，再通过 ACP 连接，检查审批、工具结果和会话结束能否正确呈现。", "升级或切换后端后，用相同小任务检查上下文、修改应用和权限；把工作流配置与模型版本一起记录。"],
    command="text\n选择路线：\n局部文本／代码转换 → HTTP Adapter → 模型\n完整项目任务 → ACP Connection → 外部代理 → 其模型与工具\n实际编辑器命令与适配器字段按当前 README 配置。",
    task="为选中的函数写清楚输入、输出与异常说明，再检查一个实际调用方是否违反约定。只在确认错误后做最小修复并解释 diff。",
    acceptance="这个任务先用轻量转换，再进入项目检查，能帮助判断何时需要完整代理。核对插件是否传入正确选区，外部后端是否获得调用方文件，以及两条路线的结果能否在编辑器中清楚审阅。",
    tradeoff="适合喜欢定制提示和编辑工作流的 Neovim 用户。优势是责任边界清楚、组合自由；代价是配置和多层排错。若希望少做配置并直接接受 AI 修改，可比较 Avante；若只想完成任务而不维护编辑器，应选择其他成品入口。")

add("B19",
    principle="Tabnine Agent 把组织控制放在显眼位置。对于企业团队，能使用哪个模型、代码发到哪里、工具能执行什么，常常比单次回答的细微差别更重要。它适合在已有 IDE 和管理策略下引入代理；但企业治理能力需要按实际部署与合同确认，不能由一个“私有”标签推断所有数据路径。",
    flow=["企业 IDE 入口\n开发任务和用户反馈", "项目上下文与组织策略\n可见文件和功能", "管理员允许的模型\n批准的服务端点", "代码变更与执行结果\n按团队流程审查", "IDE 工具及命令\n实际开发环境", "Agent 工具配置\n读取、执行与应用修改"],
    mechanism="管理员选择可用模型，用户再在允许范围内发起任务；IDE 工具设置决定能读文件、运行命令或应用修改。它把模型治理与执行控制分开，但两者都需要验证。例如模型端点在内网，并不能说明某个工具不会访问外部网站；禁止执行命令，也不等于可以随意读取全部项目资料。完整商业核心未公开，内部调度不宜臆测。",
    rows=[("组织模型策略", "管理员控制可用模型", "实际可选目录以组织和入口为准"), ("工具设置", "读取、命令与代码应用分别控制", "使用前核对有效授权而非仅看默认值"), ("开发上下文", "IDE 项目与用户反馈", "先选代表性仓库，确认项目理解有效"), ("部署路线", "企业与私有端点等方案", "数据、日志和工具出口需按部署核对"), ("模型范围", "官方目录列多个模型家族", "目录存在不代表每个入口均可使用"), ("源码边界", "商业完整运行时未公开", "以公开能力及组织试点结果评价")],
    steps=["由组织确定允许的部署、模型与数据策略，再在批准的 IDE 中启用 Agent；个人用户也应检查自己实际能选的模型。", "核对文件读取、命令执行和代码应用设置，选一个不依赖复杂外部环境的代表性项目。", "给出测试补齐或小重构任务，让代理先说明影响范围；检查它使用的上下文与团队规范是否一致。", "在组织允许的模型之间对照，记录完成、人工干预与费用；在组织批准的范围内选择和验证候选型号。", "试点通过后再扩大仓库和用户范围，安排配置更新、模型变更和权限调整的回归任务。"],
    command="text\n企业试点记录：\n部署与模型端点、组织允许的型号\n可读范围、可执行工具、代码应用方式\n代表性任务、验证结果、人工修正\n模型或策略变更后重新检查同一任务。",
    task="为现有服务补齐参数校验测试，并修复发现的一处遗漏。遵循项目规范，限制在指定模块中，交付测试证据与修改说明。",
    acceptance="除了代码质量，还要确认任务全过程遵循实际组织策略。工具被拒绝时是否给出清楚说明，模型不可用时是否透明切换，均影响团队能否可靠采用。",
    tradeoff="适合重视统一模型策略与开发环境治理的企业。选择成本主要在部署与管理，个人小项目未必需要这些能力。与其他企业 IDE 产品比较时，应使用真实组织要求和试点任务，不把宣传中的隐私词汇当作已验证事实。",kind="public")

add("B20",
    principle="Jules 把代码任务放到独立云端工作机上，让用户先交代需求，再回来查看计划与产物。与本机即时交互相比，它更依赖完整任务说明和可重复环境；优势是用户不必一直占用自己的终端。实验性质也意味着使用者应保留对功能变化、可用性和结果质量的观察。",
    flow=["GitHub／Jules／API 入口\n选择仓库和任务", "Source 与 Session\n源码范围及会话", "原生服务模型路由\n按产品提供能力", "Activity 与代码产物\n查看、审阅和交付", "云端虚拟机\n克隆、安装、修改、测试", "任务计划与代理运行\n推进和报告状态"],
    mechanism="API 将源码来源、会话与活动分为不同对象，便于调用方持续跟踪任务状态与产物。云端环境要从仓库重新建立工作条件，本机正在运行的服务、未提交文件和个人环境变量不会自动出现。CLI 是服务入口，并不意味着同样的执行引擎被搬回本机。",
    rows=[("任务方式", "异步云端编码", "适合独立 issue 与批量维护"), ("环境", "独立虚拟机准备仓库与依赖", "提供可重复安装和测试步骤"), ("API 对象", "Source、Session、Activity", "跟踪状态与产物，不能只看完成通知"), ("项目规则", "仓库说明及 AGENTS.md 等材料", "未记录背景要补入任务或仓库"), ("模型", "原生模型路由", "公开材料不支持任意 BYOK 的普遍承诺"), ("成熟度", "官方入门仍有实验性质说明", "保持小范围试点与正常人工审查")],
    steps=["连接需要处理的 GitHub 仓库，确认分支与访问范围；先选择一个环境简单、可独立验收的问题。", "准备依赖安装、测试方法和项目指令，确认云端不需要本机未提交资料；给出具体复现与期望结果。", "检查计划是否覆盖任务边界，再让它运行；出现环境问题时补齐说明，避免把环境失败当成模型不会做。", "查看活动记录和产物，核对修改与实际测试；有遗漏时，明确指出缺失的行为、文件或测试，便于继续修正。", "结果回到正常代码审查流程后再决定合并。相同维护任务反复稳定，才考虑 API 或批量任务自动化。"],
    command="text\n适合 Jules 的任务说明：\n仓库与分支、问题复现、期望行为、安装和测试步骤\n需要保留的兼容行为、交付形式与验收条件\n不依赖“我本机刚才打开的文件”或未提交改动。",
    task="为命令行工具补充帮助文档并修正一个参数边界问题。云端安装依赖后运行测试，交付代码与文档的对应修改。",
    acceptance="检查云端是否处理了正确分支，帮助文档是否与实际参数一致，测试是否真实覆盖边界。只有成功启动任务或收到通知，不能证明修改已经可合并。",
    tradeoff="适合可独立交付的小 issue、测试补齐和文档维护。对强依赖本机环境或需要密集实时讨论的工作，启动与交接成本可能更高。与 Gemini CLI 比较运行位置，与 Devin 比较任务与环境管理，模型选择则遵循各自产品开放程度。",kind="public")

add("B11",
    principle="Warp 从终端出发，把命令及其输出组织成容易理解的工作单元；原生 Agent 在此基础上完成多步操作，Automation Platform 再把稳定工作转成可触发任务。这条路线适合本来就在终端处理构建、日志和环境的人。需要先分清自己是在 Warp 里运行第三方 CLI，还是使用 Warp 自己的代理，因为两者的模型和执行逻辑不同。",
    flow=["终端／自动化触发器\n任务及命令背景", "Agent Profile／平台配置\n模型、工具与自治程度", "原生 Agent 的模型\n第三方 CLI 则另行配置", "输出、运行记录与产物\n查看后修正", "本机或远程执行环境\n命令、文件和服务", "代理工具与权限规则\n实施和编排"],
    mechanism="终端保留命令与输出，有助于模型把错误和具体操作对应起来。Profile 将模型、工具和自治程度保存为一组配置，让重复任务少一些临时设置；触发器只负责何时开始，远程环境负责在哪里执行。一个本机排障任务变成定时自动化时，输入、凭据、重复执行和失败通知都需要重新设计，不能只给同一句提示加一个时间表。",
    rows=[("终端宿主", "可运行第三方编码 CLI", "第三方核心与账单仍按其自身规则"), ("原生 Agent", "结合终端上下文与工具执行", "核对读取到的命令输出与实际运行环境"), ("Profiles", "模型、工具、自治与命令权限", "配置保存后仍需按任务限制能力"), ("自动化平台", "触发、远程环境、编排与观察", "启动成功不代表业务任务完成"), ("生命周期", "本机会话与远程任务分开", "退出终端后是否继续取决于运行路线"), ("权限", "执行凭据与命令权限共同限制影响", "产品界面的确认不能替代系统账户边界")],
    steps=["先把 Warp 当作日常终端使用，确认项目命令、输出和路径；选择原生 Agent 或第三方 CLI，明确当前执行者。", "给原生 Agent 一个解释错误或整理日志的任务，先保留审查，核对它是否读到了正确命令的输出。", "重复任务稳定后保存 Profile，写清可用工具、命令范围、模型和预期产物；排障完成后，将权限收回到日常任务所需范围。", "需要自动运行再准备独立环境与触发条件，设置不会重复产生副作用的任务边界，并明确失败后如何检查。", "在测试环境触发一次完整运行，核对日志、产物与费用。相同输入重跑时检查是否重复写入，再决定上线频率。"],
    command="text\n从临时排障到自动任务：\n解释日志 → 人工确认处理方式 → 保存 Profile\n→ 准备远程环境 → 测试触发与失败分支 → 定期检查结果\n若运行的是 Claude Code／Codex CLI，沿用相应工具的配置。",
    task="分析最近一次构建失败，定位首个相关错误并给出最小修复。修复流程稳定后，把它整理成定期检查依赖兼容性的任务，先只产出报告。",
    acceptance="排障阶段看是否抓住第一个根因，避免被后续连锁错误带偏；自动化阶段看任务输入、结果和重复执行是否可控。只有自然语言总结，没有保存实际日志或报告，就难以长期维护。",
    tradeoff="适合终端排障、开发环境和周期性工程任务。相比通用自动化平台，它更贴近开发环境；相比单纯 CLI，它提供更完整的终端与远程组织。成本是 Profile、执行环境与触发流程的维护，特别是在涉及共享系统时。",kind="public")

add("B12",
    principle="Antigravity 将代码、浏览器操作和可查看的任务产物放进同一开发流程。对 Web 开发而言，模型需要的不只是编辑文件，还要观察页面实际如何运行。计划和验证材料帮助用户检查过程，但任何可视化产物都只是证据的一种：截图可以证明某个瞬间的外观，不能证明所有交互和异常路径正确。",
    flow=["编辑器／任务入口\n项目与用户目标", "任务计划及上下文\n代码、设计和要求", "产品可选模型\nGemini 等实际目录", "计划、截图与验证产物\n审阅和反馈", "代码／终端／浏览器\n实现与运行观察", "Agent 工具执行\n按能力与权限推进"],
    mechanism="浏览器反馈把“我写了样式”变成“我看到了渲染结果”，有助于发现布局、资源和交互问题。代理仍需决定访问哪条路径、输入什么数据、如何判断成功；如果测试步骤只打开首页，报告就无法支持登录和权限已正确的结论。并行任务也应约定组件与接口边界，避免不同代理同时改全局样式或共享配置。",
    rows=[("工作对象", "代码、浏览器与任务产物", "把功能路径纳入验收，不只看生成代码"), ("计划", "可查看的任务组织材料", "用户应确认范围、假设和验证步骤"), ("视觉验证", "浏览器操作与截图等产物", "截图只支持被实际观察到的状态"), ("执行权限", "文件、终端和浏览器各有能力范围", "分别检查账户、目录和网页操作权限"), ("模型", "以当前官方模型目录为准", "不能把别处发布的型号推定为这里可选"), ("交付", "代码修改与运行材料一起审查", "还要覆盖无障碍、错误、空数据与响应式")],
    steps=["打开已有 Web 项目，确认启动命令与本地预览可用；选择当前账户可用模型，明确浏览器与项目执行范围。", "给出具体页面或流程，先让代理列计划和验收路径。设计要求应包括尺寸、组件规范和异常状态。", "实施后要求运行页面，从真实入口操作；让每个测试结果对应具体路径和可见证据。", "除了正常流程，再检查错误输入、空数据、窄屏和键盘操作。发现问题后回到代码修复，再复查受影响路径。", "保存代码、说明和验证产物，区分已运行与未运行的检查。需要并行时按页面或独立模块划分，统一全局组件和接口。"],
    command="text\n前端验收卡：\n正常路径：从入口到成功结果\n异常路径：空输入、错误返回、重试\n展示：窄屏、长文本、加载和空状态\n可用性：键盘操作、焦点和可读提示",
    task="制作一个可搜索的资料列表页，复用现有设计系统。完成后在浏览器验证加载、搜索无结果、请求错误、重试和手机宽度，交付相应证据。",
    acceptance="检查每项声称测试过的行为是否都有实际操作依据。漂亮的静态列表不能证明搜索和重试正常；自动截图也可能漏掉屏幕下方内容。适合用同一功能比较“写代码”和“运行后修正”的差异。",
    tradeoff="适合 Web 原型、前端迭代和需要视觉反馈的任务。复杂后端、数据库与权限系统仍需要相应工程验证。与普通 IDE 比较浏览器反馈是否减少返工，与托管应用平台比较部署便利和环境控制，不能只凭成品截图评分。",kind="public")

add("B13",
    principle="Replit Agent 把搭环境这件事也包含在产品里。初学者不必先理解本地依赖、预览服务器和部署步骤，就能从需求开始做应用。这降低了从想法到可运行原型的门槛；当原型成为真实业务时，数据、认证、运行费用和迁移才会变成主要问题。起步简单与长期维护简单是两个阶段的判断。",
    flow=["需求与产品入口\n目标用户、核心流程", "托管项目与任务组织\n文件、环境与上下文", "产品能力档位／路由\n按实际账户配置", "预览、检查与部署产物\n人工验收", "托管运行环境及服务\n应用、数据与依赖", "Agent 实施\n生成、修改和运行"],
    mechanism="平台同时管理代理和应用环境，所以生成代码后能较快进入预览。真正发布时，还会涉及持续运行、数据库与秘密配置；这些不是一次模型调用费用。迁移也因此应按组件检查：下载源码只带走代码，数据库内容、环境变量和部署设置可能需要另外导出与重建。能力档位由产品组合路由，不能把一个档位永久等同于某个型号。",
    rows=[("起步", "需求、代码和环境在同一平台", "适合先验证核心流程，减少本地搭建成本"), ("预览", "生成后运行并交互检查", "预览可用不等于生产部署已准备完成"), ("模型选择", "Lite／Economy／Power 等能力路线", "按任务与预算选档，不臆造固定模型映射"), ("数据与认证", "随应用引入相关服务", "先设计真实数据和账户边界"), ("费用", "Agent 使用及应用持续运行等项目", "分别记录开发成本和上线后的月成本"), ("迁移", "源码、数据库、配置与部署分别处理", "演练重建，确认离开平台还能运行")],
    steps=["先写清目标用户与一个核心流程，例如录入事项、查询和导出；第一轮先完成可运行、可验收的核心流程。", "让 Agent 生成最小版本，用预览逐步验收。发现偏差时说明具体行为，避免反复整体重做。", "准备使用真实数据前，检查存储、认证和访问规则；需要登录或支付时单独设计和验证。", "根据任务复杂度选择能力档位与预算，关注多轮返工的累计费用。较小修改优先试轻档，确有困难再提升。", "发布前核对持续运行成本与服务配置；保存源码和重建说明，试着导出必要数据。正式业务还需安排监控、备份与维护责任。"],
    command="text\n第一版需求建议控制为：\n一个主要用户角色＋一条核心流程＋少量必要数据\n验收顺序：可运行 → 流程正确 → 数据正确 → 权限正确\n随后再决定部署、付费功能与规模扩展。",
    task="做一个团队书籍借阅原型：登记书籍、借出、归还和查询。先使用测试数据，明确哪些功能只是演示，再决定真实账户与数据存储方案。",
    acceptance="用同一本书重复借出、归还不存在的记录和空字段测试业务约束。若页面完整但数据状态混乱，就仍是界面原型。记录从开始到可验收版本的总费用，包含后续修改与验证。",
    tradeoff="适合非开发者验证想法、内部小工具和演示应用。便利来自平台承担环境与部署，代价是服务依赖和迁移工作。复杂长期系统可用它做原型，但不应跳过后续工程设计；已有成熟仓库则可能更适合本地或远程编码代理。",kind="public")

add("B14",
    principle="Qoder 将项目知识与目标式执行放在一起：先帮助理解已有仓库，再推进较完整的开发任务。Repo Wiki 是一种可复用的项目说明，Quest 等方式则强调围绕目标持续工作。这个组合适合刚进入陌生项目的人。自动生成的知识材料可作为阅读线索，关键结论再回到当前代码核对。",
    flow=["桌面／IDE／CLI\n项目与目标", "Repo Wiki 与上下文\n代码知识及任务材料", "产品模型／自定义模型\n按入口配置", "任务产物及知识更新\n验证和审阅", "项目工具与工作空间\n修改、运行、检查", "Quest 等执行方式\n计划与持续推进"],
    mechanism="项目知识可以减少每次从零探索的成本，但代码持续变化后，说明也需要更新。任务运行时仍要回到真实文件确认关键行为。自定义模型与平台辅助能力又是两条费用路径：即使主要对话使用自己的 Key，Repo Wiki 等功能仍可能调用产品固定模型并消耗平台额度。因此需要按能力拆账，而非简单分成 BYOK 或订阅两类。",
    rows=[("知识材料", "Repo Wiki 等项目说明", "先核对关键入口和数据流，保留原始代码依据"), ("目标执行", "Quest 等持续任务工作方式", "完成标准需具体到结果和测试"), ("多入口", "桌面、IDE、CLI 各有配置范围", "导入不等于历史与所有配置自动互通"), ("模型", "产品目录与部分自定义 Provider", "按当前入口验证实际模型 ID"), ("辅助费用", "部分知识能力固定使用平台模型", "自有 Key 不会覆盖所有平台消费"), ("迁移", "代码、知识、规则与会话分开", "保存关键需求和检查点后再切模型或入口")],
    steps=["选定一个常用入口导入仓库，确认实际模型与计费方式；先让它说明项目结构和运行方法。", "使用项目知识功能后，抽查数据流、入口和关键业务规则；发现错误时，回到代码核实并更新相应材料。", "提交一个有明确输出的任务，用 Quest 等工作方式推进；要求保留阶段成果、测试结果和未解决事项。", "切换模型或入口前保存关键约束，再核对新会话是否读到相同材料。自定义模型单独测试工具和恢复。", "完成后检查代码与知识说明是否一致，同时核对模型费用和平台辅助能力消耗，判断是否值得长期保留。"],
    command="text\n陌生项目试用路线：\n项目知识 → 抽查三条关键事实 → 明确任务与验收\n→ 目标执行 → 检查代码与知识是否同步\n费用记录分开列：主模型、Repo Wiki 等辅助能力。",
    task="根据项目现状补充一个管理员筛选功能。先确认已有权限与查询规则，再实现；最后更新相关项目说明，指出哪些原有知识已经过时。",
    acceptance="这个任务同时检验知识与执行两层。若说明写得流畅却引用旧代码，应先修知识；若依据正确但实现不符，则检查执行模型和任务边界。关注完成后知识是否被主动或人工同步。",
    tradeoff="适合项目入门、中文开发和希望知识材料与目标执行结合的人。代价是知识维护及多路费用。与 Augment 比较时，关注检索服务与显式 Wiki 的不同；与 Kiro 比较时，关注理解现有项目和定义新需求的不同。",kind="public")

add("B15",
    principle="CodeBuddy 把代理能力放进多种开发入口，同时面向中文和腾讯相关开发生态。对于已有小程序、云服务与团队工具链的用户，现成上下文入口可能比自己拼装连接器更方便。它的价值应在真实项目中衡量；国内、国际、IDE 和 CLI 各自提供什么，不能只凭共同品牌推断。",
    flow=["IDE／插件／CLI\n需求与上下文引用", "项目规则及材料组织\n文件、Git、终端、文档", "入口可用模型\n默认或支持的自定义路线", "主任务结果与变更\n汇总、测试和审阅", "项目工具／独立子任务\n实际执行环境", "Agent 与权限配置\n工具和目录边界"],
    mechanism="精确引用报错、Git 变更和文件，可以帮助代理从正确位置开始；如果上下文没有指向真正模块，中文对话再顺畅也可能改错。CLI 自定义子代理把一类职责独立保存，主代理调用后获得汇总。工具和权限可能存在继承关系，因此“新建一个研究角色”并不天然意味着只读，要核对最终工具集。",
    rows=[("产品入口", "IDE、插件和 CLI", "功能与模型按版本和地区分别核对"), ("上下文", "文件、代码片段、文档、Git 与终端", "优先提供与问题直接相关的材料"), ("子代理", "独立职责、上下文与工具配置", "检查继承后的有效权限"), ("扩展路线", "团队、工作树、沙箱与 SDK 文档", "可用性以对应入口说明为准"), ("生态", "中文及腾讯相关开发场景", "生态熟悉度不能替代项目实际验证"), ("商业边界", "完整运行时未公开", "不推断内部一定使用某款竞品核心")],
    steps=["选定国内或国际版本及一个入口，完成登录与模型配置；查看实际权限，确认账单和组织政策。", "打开真实项目，显式引用出问题的文件、终端输出或 Git 变更；让代理先说明调用关系和运行方法。", "给出最小修复任务，保持业务边界清楚。涉及小程序或云服务时，用项目实际配置和官方接口资料核对实现。", "需要反复进行同类调查时，再在 CLI 建立职责清楚的子代理，检查其工具和权限，而不只看角色描述。", "完成后检查代码、运行结果和部署假设。需要团队或工作树再逐项试验，不把另一个入口的教程直接套过来。"],
    command="text\n给代理的上下文建议：\n相关文件＋真实报错＋当前 Git 变更＋复现路径\n然后说明：期望行为、允许修改范围、验证命令\n子代理则另外写清职责、输出格式与工具权限。",
    task="小程序的分页列表在切换筛选后出现旧数据混入。请引用现有状态管理和接口代码，修复竞态，验证快速切换、空页和网络错误。",
    acceptance="结合请求顺序和状态重置检查修复，确认根因得到处理。生态资料可以帮助定位 API，但最终应以实际项目运行和测试为准。比较不同地区版本时记录模型和工具差异，避免错误归因。",
    tradeoff="适合中文团队、相关云生态和希望兼顾插件与 CLI 的用户。优势是现成整合，代价是地区、入口与配置差异。复杂多模型研究更适合开放底座；单一生态开发则可能因少配一些东西而节省更多时间。",kind="public")

add("B06",
    principle="Zed 把编辑器与代理明确分开。用户可以保留一个轻快的编辑器，选择内置 Agent，也可以把任务交给外部完整代理。这样，喜欢某个界面与喜欢某种执行方式不必成为同一个决定。开放协议降低了入口替换成本，但不会统一所有后端的模型、工具权限和收费方式。",
    flow=["Zed 编辑器\n项目、选区与交互", "Agent 面板／ACP 连接\n会话与能力协商", "内置模型或外部代理\n各自认证与模型", "会话更新与修改结果\n回到编辑器审阅", "项目工具与终端\n由相应代理组织", "当前执行运行时\n内置 Agent 或外部核心"],
    mechanism="选择内置 Agent 时，Zed 负责组织较多代理行为；选择 ACP 时，Zed 更像客户端，把会话输入、权限交互和更新连到外部进程。这个差别会影响排错：外部模型认证失败，要检查外部代理配置；编辑器显示异常，则可能是连接或展示问题。统一面板能够减少学习入口的成本，却不能保证不同代理的历史、命令和能力一一对应。",
    rows=[("两条路线", "内置 Agent 与 ACP 外部代理", "试用时明确当前谁负责执行循环"), ("上下文", "编辑器项目线索与代理自身规则", "检查文件选择怎样进入外部会话"), ("认证", "内置模型与外部代理可分开管理", "给 Zed 配 Key 不自动登录外部代理"), ("权限", "客户端呈现交互，后端有自身执行边界", "确认远端／本机执行位置和实际授权"), ("模型选择", "取决于所选运行时", "组合应写成 Zed＋代理＋模型"), ("迁移", "统一入口有助于比较后端", "历史恢复与特殊命令仍须逐个验证")],
    steps=["安装 Zed 并打开项目，先选择内置 Agent 或一款 ACP 代理，不同时更换两条路线。", "内置路线配置模型；外部路线按 Registry 和代理文档完成安装与认证。先发一个只读查询确认连接正常。", "让代理解释当前文件与调用关系，核对编辑器选区和项目背景是否正确进入任务。", "交付一个小修改，观察权限请求、工具输出和 diff 是否完整；失败时分别检查编辑器连接与代理日志。", "用相同任务再比较第二个后端，记录模型、权限、工具及完成成本。需要恢复旧会话时单独验证，不推定所有后端互通。"],
    command="text\n请把试用对象写完整：\nZed＋内置 Agent＋所选模型\n或 Zed＋ACP 代理（如 Codex／OpenCode）＋其实际模型\n认证、权限与账单按对应后端分别核对。",
    task="在当前模块添加一个输入校验，复用现有错误类型并补测试。用两种代理后端分别完成同等任务，比较操作可见性与修改质量。",
    acceptance="先确认比较没有偷偷改变模型和任务难度。观察外部代理的操作是否在面板中清楚呈现、审批是否可理解、最后的文件状态是否一致。界面相同可以帮助控制变量，但不代表所有变量已经相同。",
    tradeoff="适合喜欢 Zed、又不想把代理选择绑定在编辑器上的开发者。代价是双层配置和排错：客户端一层、外部代理一层。与 Cursor 比较整合程度，与终端 CLI 比较编辑器便利；如果常换后端，ACP 的边界会格外有价值。")

add("B07",
    principle="TRAE／SOLO 强调从需求走到成品。编程之外，资料、数据和报告也可以作为任务对象，用户无需每一步都手动把聊天内容复制成文件。对于不想配置大量工具的人，这种工作台有吸引力；但托管产品的内部路由和运行时不完全公开，因此应通过具体成果检验，而不根据角色名推断内部架构。",
    flow=["TRAE／SOLO 入口\n需求、材料与项目", "任务及上下文组织\n按产品工作方式", "内置模型选择或路由\n地区与账户相关", "文件、预览及交付材料\n用户检查", "代码／资料处理环境\n按实际入口提供", "代理与产品工具\n执行和验证"],
    mechanism="从用户可见流程看，输入不仅是一句提问，还包括项目、附件和输出格式；代理将工作分阶段推进，并把结果放回可查看的产物。这个结构适合“先收材料、再分析、再制作”的任务。需要分别检查各阶段：读到资料不等于事实正确，生成文件不等于排版可用，原型跑起来也不等于后端、权限和部署已经完成。",
    rows=[("产品身份", "商业 TRAE／SOLO 与研究 trae-agent 分开", "研究仓库状态不能代表商业产品维护"), ("任务范围", "编程及部分资料、报告、数据工作", "按具体入口确认可交付文件与工具"), ("地区差异", "国内／国际及不同版本", "模型目录、额度和服务可用性分别核验"), ("成品流程", "任务执行与产物呈现结合", "需检查中间依据和最终文件，不只看摘要"), ("模型", "产品可选型号或内置路由", "不假定每个版本都有自由 BYOK"), ("透明程度", "商业内部实现未完整公开", "以公开接口和实用验收为证据边界")],
    steps=["选定地区与入口，检查实际模型、额度和功能；编程任务打开仓库，资料任务建立明确材料范围。", "描述读者或使用者、核心需求和输出格式。例如报告要说明篇幅、引用、图表和文件形式；应用要说明主要用户流程。", "先让代理检查材料与环境，确认缺失信息和关键假设。对不确定事实要求标明，不让它为凑齐成品自行补造。", "按阶段检查产物：先结构，再实现或正文，最后预览与验证。需求变动时明确指出哪些已有工作仍然有效。", "保存最终文件和必要源材料。涉及发布或外部服务时单独核对运行费用、账户和部署条件，再决定长期维护方案。"],
    command="text\n成品任务输入模板：\n给谁用／读：\n必须完成的三件事：\n可以使用的材料与来源：\n输出文件或应用形式：\n怎样判断完成，以及哪些事实仍需确认：",
    task="用给定访谈材料制作一份产品需求报告，包含用户问题、证据、优先级和待验证假设；每个判断能追溯到材料，交付可继续编辑的文件。",
    acceptance="这能检验资料到成品是否真正闭合。核对引文、统计、建议与证据的关系，打开最终文件检查版式与可编辑性。代码任务则额外检查运行、异常路径与依赖，不能用报告型任务的好表现推断工程可靠性。",
    tradeoff="适合希望减少配置、直接组织产物的用户。便利来自产品整合，也意味着模型路由与部署细节更受平台控制。专业开发可与 Codex／Cursor 比较；固定资料问答可与 AnythingLLM 比较；不同目标不宜共用一个排名。",kind="public")

add("B08",
    principle="Augment 的重点是让代理先拿到正确背景。大型仓库里的一个常见难点，是找到已有实现、隐含约定和跨仓库依赖。Context Engine 把查找材料放到模型之前，Auggie 再据此执行任务。这条路线在知识分散的成熟项目中更容易体现价值。",
    flow=["IDE／Auggie／其他代理\n开发问题与目标", "Context Engine\n索引、检索与权限范围", "代理的模型配置\n原生路由或外部模型", "变更及检索证据\n复查与交付", "仓库文件和开发工具\n实现及验证", "执行代理\n使用检索背景推进"],
    mechanism="索引相当于预先制作一份能检索的项目地图，查询时再挑选与任务有关的片段。这可以减少手工找文件，却会受覆盖范围、更新时机和权限影响。Context Engine 通过 MCP 提供给其他代理时，只替换了“找材料”这一层，后面的执行核心和模型仍由原工具负责。这样可以复用知识基础设施，但也要分别评价检索质量与代理实施能力。",
    rows=[("上下文服务", "Context Engine 的代码索引与检索", "用真实业务问题检验检索内容是否完整、相关"), ("仓库范围", "按配置覆盖项目与相关材料", "纳入正确依赖，比无差别扩大范围更重要"), ("时效", "索引与代码更新需要衔接", "变更后抽查是否仍返回旧实现"), ("权限", "上下文材料的可见范围", "组织资料进入检索前要有明确访问控制"), ("独立接入", "Context Engine MCP 可服务其他代理", "组合应区分检索层、执行层与模型层"), ("成本", "索引维护与实际任务调用", "检索省时需与维护及服务成本一起评估")],
    steps=["选择一个真实仓库建立索引，核对纳入与排除范围；先别急着让代理改代码。", "准备五个你知道答案的问题，如权限检查入口、配置读取路径或跨服务调用方，检查检索证据是否完整且最新。", "对漏检问题补充相关仓库或调整范围，辨认是根本没索引到、检索没命中，还是模型误解了已找到的内容。", "再让 Auggie 实施一个跨文件小修改，要求解释每项改动依赖的项目约定，并运行有关检查。", "需要保留原 Harness 时，通过文档支持的 MCP 路线连接 Context Engine，用同类任务评估这层检索是否减少探索与返工。"],
    command="text\n检索验收问题示例：\n1. 权限检查有哪些真实入口？\n2. 这个配置值在哪里被覆盖？\n3. API 字段变更会影响哪些调用方？\n答案需带文件、位置、调用关系及索引未覆盖范围。",
    task="为共享 API 增加一个可选字段。先找齐相关定义、序列化和调用方，再说明兼容方案；依据确认的依赖关系修改并验证。",
    acceptance="重点看遗漏率与证据准确性。返回很多文件不代表找齐了依赖，返回一个相似函数也不代表选中了真正入口。若模型已得到正确材料仍改错，应评估执行模型；若根本没找到关键文件，先改进上下文层。",
    tradeoff="适合大型业务仓库、跨仓库改动和新人熟悉项目。小仓库可能不需要专门索引服务。与大上下文模型比较时，应看检索能否更精准和及时；与其他 Harness 搭配时，保留双方账单与数据路径，避免把组合效果只归功于其中一方。",kind="public")

add("B09",
    principle="Amp 将任务投入做成可选择的能力档位，减少用户逐项配置模型参数的负担。档位可能同时改变模型、推理强度、工具和专家调用。这样能降低调参负担，但也意味着两次不同档位的比较，不是严格的单模型实验。产品替用户做了一部分编排决策，用户仍要判断这些额外能力是否值得。",
    flow=["CLI／编辑器等入口\n任务与能力档位", "档位配置及主代理\n提示、工具和推理设置", "主模型／专家模型\n按职责路由", "主任务上下文与交付\n汇总证据、实施验证", "Search／Oracle 等能力\n独立上下文或专门工具", "任务分派\n检索、咨询、资料与历史"],
    mechanism="主代理遇到难题时可以咨询 Oracle，调查外部材料时使用 Librarian，检索代码则有其他专门能力。这些职责通常交回结论，帮助主对话避免被大量中间过程占满。它们不是必然彼此通信的一个团队。升档增加的能力可能减少返工，也可能对简单任务产生额外调用，因此可以结合总耗时、调用量和人工纠正次数评估升档收益。",
    rows=[("能力档位", "low／medium／high／ultra 等组合配置", "档位不只是模型名或单一推理参数"), ("专家分工", "Search、Oracle、Librarian 等", "核对角色实际职责，不按名称幻想权限"), ("上下文", "专门任务与主任务之间进行汇总", "交接需要证据和文件位置，不能只有结论"), ("历史", "Read Thread 等历史访问能力", "历史可访问不代表每轮自动全部读入"), ("远程环境", "Orbs 等持久工作路线", "另检查环境、凭据与生命周期"), ("可复现性", "官方路由可能随产品更新", "记录档位、实际模型、工具配置和版本")],
    steps=["按官方入门选择入口，先用中等能力档位做一项你熟悉的任务，保存完成结果与成本。", "任务中要求指出依据和验收；观察主代理在什么情况下调用专门能力，以及汇总是否真的帮助推进。", "对确实失败或困难的环节升档，比较是否减少错误或人工干预，不仅比较措辞与推理长度。", "需要持久远程环境再配置 Orbs；先验证项目运行、资料可用性和结果保存，而不把远程环境等同于更强模型。", "再考虑插件或自定义分工，清楚规定输入、输出和工具；保留标准档位任务作为升级后的回归基线。"],
    command="text\n对照记录：相同仓库与任务\nmedium：实际模型／专家调用／耗时／成本／人工纠正\nhigh：同样记录，并解释新增能力改善了哪一步\n只有验收一致时，成本差异才有可比性。",
    task="调查一个偶发并发错误，给出可验证的根因、最小修复和回归测试。需要额外推理时说明要咨询的问题，交付时保留支持结论的代码证据。",
    acceptance="困难调试适合检验专家分工。重点看咨询是否提出了新且可验证的假设，主代理是否据此重现并修复；多个角色重复同一句猜测不能算相互验证。",
    tradeoff="适合希望减少配置、愿意由产品选择执行组合的熟练用户。代价是模型和工具变化的透明度要求更高，升档收益需以实际完成任务衡量。要严格固定模型研究循环，可比较 Pi／mini-SWE-agent；要规范化交付流程，可比较 Factory。",kind="public")

add("B10",
    principle="Factory Droid 把大任务看成一组需要交接和验证的工作。Missions 的价值不在于能开多少代理，而在于规划者、工作者与验证之间有可查看的材料和完成条件。只有接口明确、各部分能检验时，拆分才可能提高吞吐；需求模糊时增加工作者，往往只是更快地产生彼此不一致的代码。",
    flow=["CLI／Desktop／Mission\n目标与验收标准", "规划与任务组织\n共享接口和工作分配", "角色模型配置\n原生目录或适用 BYOK", "集成与验证结果\n修正后交付", "工作者及执行环境\n独立任务与项目工具", "Droid 工具及权限\n按角色和运行方式约束"],
    mechanism="自定义 Droid 文件为一类任务定义职责、模型和工具，被调用后拥有自己的上下文。这让主任务可以把大量实现细节交出去，但也失去对子任务隐含假设的直接掌握。非交互工作者无法随时追问用户，因此规划阶段要把必要信息给足。验证者应依据代码与运行结果判断，不能只是重新读取工作者的成功总结。",
    rows=[("任务层次", "普通 Droid 与 Missions", "小任务不一定需要完整编排"), ("角色配置", "Markdown 定义职责、模型和工具", "角色描述要能转化为明确的交付件"), ("上下文", "子代理拥有独立任务上下文", "接口与共享事实需要显式传递"), ("工作者限制", "某些非交互路径限制提问和继续派生", "不确定信息应在任务下发前解决"), ("模型独立", "CLI／Desktop 等入口有 BYOK 路线", "不把该能力扩展到所有托管入口"), ("完成控制", "计划、实施和验证组成交付过程", "证据需独立可查，避免代理自评替代验收")],
    steps=["从单个 Droid 开始，完成一个小功能，确认模型、权限、沙箱和测试都能工作；先选边界清楚的小任务试用 Mission。", "挑选能拆分的需求，定义共享接口、目录责任和验收方式。例如先统一 API 契约，再分配前后端实现。", "按职责配置工作者的模型和工具，给非交互子任务完整输入；预算中同时计入规划、实施与验证。", "检查中间产物是否符合接口，再集成修改；冲突交给有完整上下文的主任务处理，不让工作者相互猜测。", "用独立检查核对真实运行结果，记录遗漏与返工。重复成功后再扩大任务规模或引入自定义模型。"],
    command="text\nMission 任务拆分示例：\n共享契约：请求参数、响应结构、错误码、目录责任\n工作者 A：后端接口与测试\n工作者 B：按契约实现前端\n集成验收：真实用户流程、异常路径与回归检查",
    task="增加一个可筛选的管理页面。先定义接口与权限规则，再分别实现后端、前端和测试，最后统一集成并展示验收证据。",
    acceptance="看任务交接能否减少返工：前后端是否使用同一字段，权限是否只停留在界面，验证是否真的从用户入口走完整流程。并行速度快但最后大量重写，并不说明编排有效。",
    tradeoff="适合完整功能、重复开发流程和愿意维护角色配置的团队。代价是前期拆分、调用成本与集成负担。高度耦合的小修复通常交给单代理更直接；多代理收益可结合总交付时间、集成成本和返工量判断。",kind="public")

add("B01",
    principle="Cursor 把代理放在开发者已经工作的编辑器里。当前文件、选区、诊断和项目搜索共同构成任务起点，用户可以边看代码边修正代理方向。这降低了交接成本，尤其适合需求逐步成形的界面开发。与一次性把 issue 交给远程工作者不同，这条路线的收益很大一部分来自人与代理之间快速来回，而非无人参与的最长运行时间。",
    flow=["编辑器／Agent 入口\n选区、文件与需求", "上下文与规则组织\n项目索引和检索", "模型选择／Auto 路由\n按当前产品配置", "变更、对话及产物\n用户审阅后继续", "项目工具与工作环境\n本地或云端任务", "Agent 及子任务\n工具操作与分工"],
    mechanism="代码索引相当于项目的查找目录：它先帮助找相关材料，再由模型根据本轮任务阅读和行动。索引能减少盲目搜索，但被排除的文件、陈旧内容和隐含业务规则仍可能遗漏。子代理可以承接调查，主代理再整合结果。云端 Agent 则多出独立环境、仓库授权和结果取回过程，所以本地 Agent 跑通并不能证明云端任务也已配置好。",
    rows=[("即时上下文", "文件、选区、诊断与项目线索", "给出具体入口通常比泛泛要求重写项目有效"), ("项目索引", "检索相关代码后进入模型上下文", "用已知答案抽查检索，不把索引视为整仓理解"), ("交互方式", "补全、局部编辑与多步 Agent", "按任务尺度选择，减少不必要的长循环"), ("分工", "子代理与项目协调等能力", "独立探索后仍需检查接口和文件冲突"), ("云端", "独立任务环境与自动化", "重新配置依赖、秘密信息与仓库权限"), ("模型", "Auto／Composer 与可选固定型号", "比较时记录实际路由、模式和账单规则")],
    steps=["安装并打开真实仓库，等待必要的项目初始化；选择当前账户可用的模型或 Auto 路线，确认相关规则生效范围。", "先选中一个模块，请代理解释职责与调用关系。用你已知的信息校验它是否找到了正确文件，再补充未写在代码里的业务约束。", "修改小区域时用局部编辑；跨文件任务再用 Agent。要求列出改动范围，边看 diff 边反馈，不让无关重构混入功能实现。", "让代理运行项目检查，并在你熟悉的预览或调试流程中检查真实行为；前端任务同时测试异常与空状态。", "需要离开电脑后继续处理独立任务，再试云端环境。单独验证环境启动、凭据范围和结果取回，最后将补丁放回正常审查流程。"],
    command="text\n打开仓库 → 检查规则与索引范围 → 选择模型／Auto\n选中相关文件并提出任务 → 审阅修改 → 运行项目检查\n云端任务另行确认：仓库、环境脚本、凭据、结果分支。",
    task="这个设置页面需要增加“保存中”和“保存失败”状态。请复用现有组件与请求层，保留原布局，验证快速重复点击、请求失败后重试和成功反馈。",
    acceptance="试用重点是交互速度与项目一致性：它是否沿用了已有样式和状态管理，能否根据你的即时反馈收缩修改。除初始页面外，还要检查后续交互；按钮重复提交、错误恢复和键盘操作都可能暴露真实问题。",
    tradeoff="适合经常边写边调、希望 AI 与编辑器融为一体的人。代价是更依赖产品模型路由与配置体系，云端功能还增加环境边界。若已有非常固定的编辑器习惯，可先比较插件或 ACP 宿主；若强调可修改运行时，则比较开放 CLI。",kind="public")

add("B02",
    principle="Copilot 的优势是把 AI 接进已有协作对象：开发者在 IDE 工作，团队通过 issue 表达需求，通过 PR 审阅结果。对于已经使用 GitHub 的组织，账户、代码权限与协作流程的整合往往比另装一套代理更省沟通成本。但它是多个产品入口的集合，必须先选清楚具体是哪一条路线，才能讨论模型、权限和费用。",
    flow=["IDE／CLI／GitHub 任务\n选择入口及仓库", "入口的上下文与规则\n代码、issue、组织策略", "可用模型与服务路由\n按入口及账户开放", "diff／活动记录／PR\n人工与 CI 审查", "本地项目或云端环境\n依赖、工具、测试", "对应 Agent 运行\n计划与修改验证"],
    mechanism="IDE 代理围绕当前开发环境工作；云端代理则需要从仓库、任务说明和环境配置重新建立上下文。因此，口头说过但没有写进 issue 的背景，远端任务未必知道。PR 提供了清楚的交接点：需求、补丁、CI 与人工评审能放在一起；但 PR 是交付容器，不是质量证明。公开的编辑器侧源码也不能替代云端服务端实现的证据。",
    rows=[("入口差异", "补全、IDE Agent、CLI 与云端代理", "先选入口，再查模型和权限，不按品牌一概而论"), ("协作载体", "issue、分支与 PR", "验收标准放进任务，结果回到正常审查"), ("组织治理", "账户、仓库访问与模型可用性", "个人能选的模型不一定获组织允许"), ("执行环境", "IDE 附近的本地环境或云端环境", "云端需独立准备依赖和所需资料"), ("源码边界", "编辑器侧实现与闭源托管部分并存", "旧仓库迁移不能解读成全产品停止"), ("完成定义", "任务产物与后续审查分开", "创建 PR 后仍需测试、审阅和合并决定")],
    steps=["确认组织政策和订阅，选择你实际会用的入口。先在 IDE 中检查模型目录、工具权限和项目指令，建立基础体验。", "用一个有测试的小 bug 验证本地代理，记录它需要哪些隐含背景；把可复用背景整理成仓库说明。", "迁到云端前，把需求改写成独立 issue：复现步骤、期望行为、文件范围、测试命令和不应改变的接口都写明。", "核对云端环境与仓库访问后再启动任务，跟踪计划与执行结果；遇到环境失败，修正准备步骤，不靠反复重试期待偶然成功。", "审阅产出的 PR，检查 diff、CI 和需求对应关系。批量维护从一类成熟任务开始，再扩大到更多仓库。"],
    command="text\n适合交给云端代理的 issue 模板：\n现象与复现：\n期望行为与兼容边界：\n涉及模块与已知线索：\n环境准备和测试命令：\n完成标准与需要人工确认的事项：",
    task="修复文档生成脚本在空目录时报错的问题。issue 中给出最小复现、预期输出和测试入口；代理完成后提交可审阅变更，并解释是否影响现有构建。",
    acceptance="看它能否仅凭 issue 与仓库材料独立推进，检验任务说明是否充分。PR 的描述应与真实修改一致，CI 通过后还要检查空目录这个具体需求是否被覆盖。",
    tradeoff="适合已经围绕 GitHub 组织工作的团队，尤其是标准化维护与异步修复。高度整合能降低交接成本，也会把部分选择绑定到组织政策和平台。需要自由控制执行环境可比较 OpenHands；需要更即时的编辑器互动可比较 Cursor 或 Cline。",kind="public")

add("B03",
    principle="Devin 产品家族同时覆盖本地开发交互与远程任务。远程路线以任务委托为主要交互方式：用户提供完整的任务说明，服务准备环境并持续执行，再由用户检查产物。能否成功很大程度取决于任务边界和环境准备，不能只把表现归因于一个模型名字。",
    flow=["Desktop／云端任务入口\n需求与仓库选择", "项目知识和环境准备\n索引、说明、依赖", "产品模型路由\n按入口的可选能力", "任务产物与审阅\n分支、报告及变更", "本地／托管／Outposts\n工具与实际工作机", "Agent 会话与编排\n推进任务和交接"],
    mechanism="本地模式可以利用开发者正在使用的环境，远端则要自己拉代码和准备依赖。项目索引或 DeepWiki 帮助代理找背景，却不能补出从未记录的业务决策。Outposts 又把环境控制转向组织管理的基础设施；这提升环境可控性，也把运维责任带回团队。比较时应把入口、运行位置和模型路由三者同时记下来。",
    rows=[("本地与远端", "Desktop 交互和异步任务", "即时协作与完整委托适合不同任务"), ("代码知识", "项目索引、知识材料及相关服务", "先用已知问题验证理解，别把文档生成视为事实核验"), ("环境", "托管与 Outposts 等路线", "自管环境需要安装、网络和资源维护"), ("长任务", "会话推进与任务产物交接", "需求、进度和验收必须能独立理解"), ("模型", "Desktop／CLI 选择与云端路由有差异", "不推定所有入口都支持任意 BYOK"), ("交付", "代码、分支、执行结果", "任务完成后仍进入团队审查与测试")],
    steps=["先决定自己需要本地协作还是远程委托，选定一个入口；检查可用模型、仓库授权和账户费用。", "为远程任务准备可重复的环境步骤，让它在未改代码前跑通现有检查。涉及内部服务时明确访问方式和可替代测试。", "给出独立完整的任务，要求先确认理解与关键接口；把聊天中已经确认的关键背景也写入任务说明。", "中途查看真实产物、日志和阻塞原因；卡住时补充具体信息，例如复现线索、环境要求或验收条件。", "完成后核对需求、diff 与测试，整理哪些信息缺失导致返工。相似任务重复成功后，再尝试并行委托或组织自管环境。"],
    command="text\n远程任务交接包：需求说明＋固定仓库状态＋环境准备\n＋可运行检查＋接口约束＋期望产物\n回收时核对：修改范围、测试证据、遗留问题、运行成本。",
    task="将一个内部 SDK 从旧接口迁到新接口，保持公开方法签名。先处理一个模块，交付兼容性说明与测试；验证通过后再扩展到其余模块。",
    acceptance="迁移试点能揭示环境与任务委托成本。若大部分时间花在缺失凭据或理解未写出的接口约定，先改善交接材料。同时检查新接口调用与原有行为的兼容性。",
    tradeoff="适合能拆成独立交付件的中长任务、异步维护和批量迁移。小改动可能被环境启动与交接成本抵消。与 Jules 比较任务控制和环境需求，与 OpenHands 比较可控性和自管成本，而非只比较宣传中的自治时长。",kind="public")

add("B04",
    principle="Kiro 将需求、设计和任务列表视为开发过程中持续使用的材料。模型围绕可持续修订的规范推进工作。对业务规则多、需要跨人交接的功能，这可以减少来回解释；对已经完全明确的一行修复，则可能增加不必要的文档成本。规范是否有用，要看它能否帮助澄清分歧、指导实施和检查结果。",
    flow=["IDE／CLI／其他客户端\n需求与人工修订", "Spec／Steering 等材料\n需求、设计、任务", "统一 Harness 与模型\n按选定模式执行", "任务进度与验证产物\n回写规范并交付", "项目工具／MCP\n代码与外部服务", "权限、Hooks 与技能\n约束及扩展行为"],
    mechanism="需求说明应回答用户要什么，设计说明回答准备用什么结构实现，任务列表回答当前先做哪一小步。三者形成可查看的交接材料，但它们也可能过时：代码改了、业务条件变了，就需要同步修订。统一进程 Harness 和 ACP 解决跨入口复用；Spec 解决工作方法，两者是不同层面的设计，不能把用了同一核心理解成所有客户端功能完全一样。",
    rows=[("需求材料", "Spec 将需求、设计与任务显式保存", "用户需删掉空话，补上例外和验收"), ("长期规则", "Steering 等持续背景", "区分全项目约定与一次任务进度"), ("跨入口", "统一核心与 ACP 等连接方式", "逐入口确认支持程度和可见功能"), ("扩展", "Hooks、MCP、Skills 等", "确定性触发与模型判断的方法要分清"), ("模型", "Auto 及当前可选型号", "档位变化后用同一规范测试结果"), ("维护", "规范与代码需要共同演进", "完成后清除过时任务，记录真实设计差异")],
    steps=["打开一个已有项目，确认构建和测试能运行；选择一个真正需要业务说明的小功能，从当前产品入口创建相应任务。", "让代理形成需求材料，逐条检查对象、输入、输出、边界和异常；不懂的业务点由人决定，不让模型默默补成假设。", "审阅设计，确认数据结构、接口和依赖符合现有项目。将大任务拆成能独立验证的小步，避免一项任务涵盖整个系统。", "逐步实施并核对产物；需求发生变化时先更新规范，再继续改代码，减少前后解释不一致。", "收尾时对照验收标准检查，更新实际采用的设计和遗留事项。简单后续修复直接对话即可，不必强迫所有任务重走完整规范流程。"],
    command="text\n需求示例：用户可以撤销尚未发货的订单。\n必须明确：谁可撤销、截止状态、重复请求、库存回补、失败提示。\n设计确认后拆任务：状态规则 → 接口 → 界面 → 验收。\n每项任务都对应可观察的结果。",
    task="增加订单撤销功能。先整理需求与异常场景，明确库存回补和幂等规则，再设计接口与状态变化；逐步实现并对照规范验收。",
    acceptance="最有辨识度的指标是规范能否减少返工。检查“重复撤销不能重复回补库存”这类关键规则是否同时出现在需求、实现和测试里。文档很完整但代码漏了约束，说明流程尚未闭合。",
    tradeoff="适合需求需要讨论、多人需要共识、中等以上复杂度的功能。代价是规范维护与前期思考，过度使用会拖慢简单任务。与直接执行型 CLI 比较时，应同时计入代码生成、文档整理和返工时间。",kind="public")

add("B05",
    principle="Junie 利用 JetBrains IDE 已经建立的项目理解：符号、引用、诊断与运行配置能为代理提供比纯文本更有结构的入口。对于依赖 IDE 的大型 Java、Kotlin 或 Python 项目，沿用这些能力可以减少重新建立工作环境的成本。前提是项目本身已经正确加载；错误的 SDK 或构建配置不会因为加了模型就自动消失。",
    flow=["JetBrains／CLI 等入口\n任务与项目", "IDE 语义及项目材料\n符号、诊断、运行配置", "规划／实施模型配置\n按当前产品选择", "计划与变更产物\n审阅、验证及交付", "IDE／终端执行能力\n修改、构建与测试", "Junie 任务执行\n结合项目工具推进"],
    mechanism="文本搜索擅长找字符串，IDE 的语义能力则可以帮助区分同名符号、调用与类型关系。代理因此有机会做更精确的定位，但是否正确仍要看实际操作与补丁。规划和实施可以使用不同模型，是把成本投入与职责分开的一种方法；如果规划中的接口约定没有进入实施上下文，再强的规划模型也无法保证最终一致。",
    rows=[("项目理解", "IDE 的导航、符号、诊断与运行配置", "先确认项目索引与构建正确"), ("规划材料", "可编辑、可保留的设计与交付说明", "计划需要具体到接口和兼容要求"), ("实施", "在既有开发环境修改并验证", "代理用的运行配置应与人工一致"), ("入口", "IDE 之外还有 CLI／CI 等路线", "逐个入口确认可用的代码理解能力"), ("模型", "当前产品提供 BYOK／本地等配置路线", "部署路线和具体型号仍需账户与版本核对"), ("成本", "规划和实施可分配不同能力", "以整项任务及返工衡量，不能只看实施模型便宜")],
    steps=["在日常使用的 JetBrains 项目中启用 Junie，先修好 SDK、依赖和运行配置；人工运行一次原有测试建立基线。", "给出一个模块级任务，让它说明将使用哪些项目线索与检查；补入隐藏业务约定和不可变接口。", "较大任务先审阅计划材料，特别检查类职责、调用方和迁移顺序。选择当前支持的规划与实施模型组合。", "实施后在 IDE 查看真实 diff、诊断和测试；确认不是通过削弱断言、跳过测试或改运行配置掩盖问题。", "同类任务稳定后再考虑 CLI／CI 或本地模型路线；重新验证环境与模型能力，而不把 IDE 试用结论直接照搬。"],
    command="text\nIDE 项目检查：SDK／解释器正确 → 依赖可解析\n→ 原有运行配置可用 → 测试基线可重现\n再让 Junie：分析符号与调用方 → 修改 → 用同一配置验证。",
    task="将这个服务的一个旧数据访问接口迁移到新接口，保持调用方行为。请查清所有引用，分批改动，并用现有运行配置执行相关测试。",
    acceptance="重点观察语义导航是否帮助找齐真实调用方，以及是否误改同名但无关的接口。大型项目还要区分编译成功与业务测试通过；如果只有某个 IDE 缓存状态下成功，应重新检查环境。",
    tradeoff="适合已有 JetBrains 工作习惯和复杂 IDE 项目的团队。优势来自环境整合，换成不熟悉或不支持的项目体系后未必同样明显。与 Cline、Cursor 比较时，先评估是否值得迁移编辑器；与 CLI 比较时，看语义工具带来的收益能否抵消环境依赖。",kind="public")
